solutionDiagrams.code:
% mathsmap-diagram-colours {"version":1,"kind":"graph","base":[],"semantic":[],"reference":"source page 53 p53-q4-solution-number-line"}
\begin{tikzpicture}[x=5cm,y=1cm]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\path[use as bounding box] (-0.1,-1.05) rectangle (2.1,1.1);
\draw[black,line width=0.5pt,<->] (-0.08,0)--(2.08,0);
\foreach \x in {0,2}{\draw[black,line width=0.4pt] (\x,-0.08)--(\x,0.08);}
\node[below] at (0,-0.08) {\special{dvisvgm:raw <g data-graph-text="tick">}$0$\special{dvisvgm:raw </g>}};
\node[below] at (2,-0.08) {\special{dvisvgm:raw <g data-graph-text="tick">}$2$\special{dvisvgm:raw </g>}};
\foreach \x in {0.02,0.17,0.355555556,0.5,0.6,0.75,0.8,1.8}{\fill[black] (\x,0) circle[radius=1.1pt];}
\draw[black,line width=0.4pt] (0.02,0)--(0.02,0.38);
\node[above] at (0.02,0.38) {$0.02$};
\draw[black,line width=0.4pt] (0.17,0)--(0.17,-0.6);
\node[below] at (0.17,-0.6) {$17\%$};
\draw[black,line width=0.4pt] (0.355555556,0)--(0.355555556,0.72);
\node[above] at (0.355555556,0.72) {$0.3\dot{5}$};
\draw[black,line width=0.4pt] (0.5,0)--(0.5,-0.36);
\node[below] at (0.5,-0.36) {$\frac{1}{2}$};
\draw[black,line width=0.4pt] (0.6,0)--(0.6,0.3);
\node[above] at (0.6,0.3) {$\frac{3}{5}$};
\draw[black,line width=0.4pt] (0.75,0)--(0.75,0.78);
\node[above] at (0.75,0.78) {$75\%$};
\draw[black,line width=0.4pt] (0.8,0)--(0.8,-0.6);
\node[below] at (0.8,-0.6) {$0.8$};
\draw[black,line width=0.4pt] (1.8,0)--(1.8,0.3);
\node[above] at (1.8,0.3) {$1\frac{4}{5}$};
\end{tikzpicture}
